  fc_repair_text: { en: 'Last night got tense? Try:', hi: 'कल रात तनाव हुआ? ऐसा कहकर देखें:', mr: 'काल रात्री ताण आला? असं म्हणून पाहा:', gu: 'ગઈ રાત્રે તણાવ થયો? આમ કહી જુઓ:' },
  fc_repair_line: { en: '“I was short with you. I’m sorry. What would help right now?”', hi: '“मैं रूखा था, माफ़ करना। अभी क्या मदद करेगा?”', mr: '“मी तुटक बोललो, माफ कर. आत्ता काय मदत करेल?”', gu: '“હું રૂખો હતો, માફ કરજે. હમણાં શું મદદ કરશે?”' },
  fc_learn: { en: '2-minute lesson', hi: '2 मिनट की सीख', mr: '2 मिनिटांचा धडा', gu: '2 મિનિટનો પાઠ' },
  fc_learn_title: { en: 'What is perimenopause?', hi: 'पेरिमेनोपॉज़ क्या है?', mr: 'पेरिमेनोपॉज म्हणजे काय?', gu: 'પેરિમેનોપોઝ શું છે?' },
  fc_teen: { en: 'For Anaya · teen-friendly', hi: 'अनाया के लिए · टीन-फ्रेंडली', mr: 'अनायासाठी · टीन-फ्रेंडली', gu: 'અનાયા માટે · ટીન-ફ્રેન્ડલી' },
  fc_teen_title: { en: 'Why is Mom so tired lately?', hi: 'मम्मी आजकल इतनी थकी क्यों रहती हैं?', mr: 'आई हल्ली इतकी थकलेली का असते?', gu: 'મમ્મી આજકાલ આટલાં થાકેલાં કેમ રહે છે?' },
