  fc_help: { en: 'Need help understanding', hi: 'समझने में मदद चाहिए', mr: 'समजायला मदत हवी', gu: 'સમજવામાં મદદ જોઈએ' },
  fc_thanks: { en: 'Thank you, Rajesh. Sunita will see a small 💛 — nothing else.', hi: 'धन्यवाद राजेश। सुनीता को बस एक छोटा 💛 दिखेगा — और कुछ नहीं।', mr: 'धन्यवाद राजेश. सुनीताला फक्त एक छोटं 💛 दिसेल — बाकी काही नाही.', gu: 'આભાર રાજેશ. સુનીતાને બસ એક નાનું 💛 દેખાશે — બીજું કંઈ નહીં.' },
  fc_help_reply: { en: "Of course. Here's a 2-minute lesson — no jargon.", hi: 'ज़रूर। यह रही 2 मिनट की आसान सीख।', mr: 'नक्कीच. हा घ्या 2 मिनिटांचा सोपा धडा.', gu: 'ચોક્કસ. આ રહ્યો 2 મિનિટનો સરળ પાઠ.' },
