  fl_pending: { en: 'Pending clinician review', hi: 'चिकित्सक समीक्षा बाकी', mr: 'वैद्यकीय तज्ज्ञांची समीक्षा बाकी', gu: 'ચિકિત્સક સમીક્ષા બાકી' },
