  cs_core_s: { en: 'Only what you tap to confirm is saved. Never your words.', hi: 'सिर्फ़ वही सहेजा जाता है जिसे आप पक्का करें। आपके शब्द कभी नहीं।', mr: 'फक्त तुम्ही पक्के कराल तेच साठवले जाते. तुमचे शब्द कधीच नाही.', gu: 'ફક્ત તમે પાક્કું કરો તે જ સચવાય છે. તમારા શબ્દો ક્યારેય નહીં.' },
  cs_family: { en: 'Send small signals to people I choose', hi: 'मेरे चुने हुए लोगों को छोटे संकेत भेजें', mr: 'मी निवडलेल्या लोकांना छोटे संकेत पाठवा', gu: 'મેં પસંદ કરેલા લોકોને નાના સંકેત મોકલો' },
  cs_family_s: { en: 'They see one short kind line, never your words.', hi: 'उन्हें एक छोटी दयालु पंक्ति दिखती है, आपके शब्द कभी नहीं।', mr: 'त्यांना एक छोटी दयाळू ओळ दिसते, तुमचे शब्द कधीच नाही.', gu: 'તેમને એક નાની માયાળુ લાઇન દેખાય છે, તમારા શબ્દો ક્યારેય નહીં.' },
  cs_brief: { en: 'Make a summary for my doctor', hi: 'मेरे डॉक्टर के लिए सार बनाएँ', mr: 'माझ्या डॉक्टरांसाठी सारांश बनवा', gu: 'મારા ડૉક્ટર માટે સારાંશ બનાવો' },
  cs_brief_s: { en: 'Built from your confirmed logs. You decide who sees it.', hi: 'आपके पुष्टि किए लॉग से बनता है। कौन देखे, आप तय करती हैं।', mr: 'तुमच्या पुष्टी केलेल्या लॉगवरून बनतो. कोण पाहील ते तुम्ही ठरवता.', gu: 'તમારા પુષ્ટિ કરેલા લૉગમાંથી બને છે. કોણ જુએ તે તમે નક્કી કરો છો.' },
  cs_employer: { en: 'Count me in anonymous workplace totals', hi: 'अनाम कार्यस्थल आँकड़ों में मुझे गिनें', mr: 'अनामिक कामाच्या ठिकाणच्या आकड्यांत मला मोजा', gu: 'અનામી કાર્યસ્થળ આંકડામાં મને ગણો' },
  cs_employer_s: { en: 'Only group totals of 10+ people. Never your name.', hi: 'सिर्फ़ 10+ लोगों के समूह के कुल आँकड़े। आपका नाम कभी नहीं।', mr: 'फक्त 10+ लोकांच्या गटाचे एकूण आकडे. तुमचे नाव कधीच नाही.', gu: 'ફક્ત 10+ લોકોના જૂથના કુલ આંકડા. તમારું નામ ક્યારેય નહીં.' },
  cs_research: { en: 'Share anonymous data for research', hi: 'शोध के लिए अनाम डेटा साझा करें', mr: 'संशोधनासाठी अनामिक डेटा शेअर करा', gu: 'સંશોધન માટે અનામી ડેટા શેર કરો' },
  cs_research_s: { en: 'Combined with others, no names. Needs 10+ people.', hi: 'दूसरों के साथ मिलाकर, बिना नाम। 10+ लोग ज़रूरी।', mr: 'इतरांसोबत एकत्र, नावाशिवाय. 10+ लोक आवश्यक.', gu: 'બીજા સાથે ભેળવીને, નામ વગર. 10+ લોકો જરૂરી.' },
  cs_audio: { en: 'Keep my voice recordings', hi: 'मेरी आवाज़ की रिकॉर्डिंग रखें', mr: 'माझ्या आवाजाचे रेकॉर्डिंग ठेवा', gu: 'મારા અવાજનું રેકોર્ડિંગ રાખો' },
  cs_audio_s: { en: 'Off by default. Voice is processed and not kept.', hi: 'डिफ़ॉल्ट रूप से बंद। आवाज़ प्रोसेस होकर रखी नहीं जाती।', mr: 'डिफॉल्ट बंद. आवाज प्रोसेस होतो, ठेवला जात नाही.', gu: 'ડિફૉલ્ટ બંધ. અવાજ પ્રોસેસ થાય છે, રખાતો નથી.' },
  cs_agree: { en: 'Save my choices', hi: 'मेरी पसंद सहेजें', mr: 'माझी निवड साठवा', gu: 'મારી પસંદગી સાચવો' },
