  wx_unknown: { en: 'Add your city in the Me tab to see tomorrow\'s weather.', hi: 'कल का मौसम देखने के लिए "मैं" टैब में अपना शहर जोड़ें।', mr: 'उद्याचे हवामान पाहण्यासाठी "मी" टॅबमध्ये तुमचे शहर जोडा.', gu: 'આવતીકાલનું હવામાન જોવા "હું" ટૅબમાં તમારું શહેર ઉમેરો.' },
  wx_estimate: { en: 'An estimate from your own logs and the forecast. Not a medical prediction.', hi: 'आपके अपने लॉग और पूर्वानुमान से अनुमान। चिकित्सा भविष्यवाणी नहीं।', mr: 'तुमच्या लॉग आणि अंदाजावरून अंदाज. वैद्यकीय भाकीत नाही.', gu: 'તમારા લૉગ અને આગાહીથી અંદાજ. તબીબી આગાહી નથી.' },
  wx_tell: { en: 'Tell my family', hi: 'परिवार को बताएँ', mr: 'कुटुंबाला सांगा', gu: 'પરિવારને જણાવો' },
  gm_morning: { en: 'Good morning, {name}', hi: 'सुप्रभात, {name}', mr: 'सुप्रभात, {name}', gu: 'સુપ્રભાત, {name}' },
