  rx_1: { en: 'Let your shoulders drop. Unclench your jaw.', hi: 'कंधे ढीले छोड़ें। जबड़े को ढीला करें।', mr: 'खांदे सैल सोडा. जबडा सैल करा.', gu: 'ખભા ઢીલા છોડો. જડબું ઢીલું કરો.' },
  rx_2: { en: 'Breathe in slowly through your nose, for four counts.', hi: 'नाक से धीरे-धीरे साँस लें, चार गिनती तक।', mr: 'नाकाने हळूहळू श्वास घ्या, चार मोजेपर्यंत.', gu: 'નાકથી ધીમે ધીમે શ્વાસ લો, ચાર ગણતરી સુધી.' },
  rx_3: { en: 'Now breathe out slowly, for six counts, like cooling a cup of tea.', hi: 'अब धीरे-धीरे साँस छोड़ें, छह गिनती तक, जैसे चाय ठंडी कर रही हों।', mr: 'आता हळूहळू श्वास सोडा, सहा मोजेपर्यंत, चहा गार करत असल्यासारखे.', gu: 'હવે ધીમે ધીમે શ્વાસ છોડો, છ ગણતરી સુધી, જાણે ચા ઠંડી કરતા હો.' },
  rx_4: { en: 'Picture cool water over your wrists. Feel the coolness spread.', hi: 'सोचिए कि कलाइयों पर ठंडा पानी बह रहा है। ठंडक फैलती महसूस करें।', mr: 'मनगटांवर थंड पाणी वाहत आहे अशी कल्पना करा. थंडावा पसरतोय असे जाणवू द्या.', gu: 'કલ્પના કરો કે કાંડા પર ઠંડું પાણી વહે છે. ઠંડક ફેલાતી અનુભવો.' },
  rx_5: { en: 'Name three things you can see in the room.', hi: 'कमरे में दिखने वाली तीन चीज़ों के नाम लें।', mr: 'खोलीत दिसणाऱ्या तीन गोष्टींची नावे घ्या.', gu: 'રૂમમાં દેખાતી ત્રણ વસ્તુઓનાં નામ લો.' },
  rx_6: { en: 'You are safe in this moment. Take one more slow breath.', hi: 'इस पल में आप सुरक्षित हैं। एक और धीमी साँस लें।', mr: 'या क्षणी तुम्ही सुरक्षित आहात. आणखी एक हळू श्वास घ्या.', gu: 'આ ક્ષણે તમે સુરક્ષિત છો. વધુ એક ધીમો શ્વાસ લો.' },
  ci_day1: { en: '1 day checked in this week', hi: 'इस हफ़्ते 1 दिन बात हुई', mr: 'या आठवड्यात 1 दिवस बोललो', gu: 'આ અઠવાડિયે 1 દિવસ વાત થઈ' },
  wx_offline: { en: 'Tomorrow\'s forecast is not available right now.', hi: 'कल का पूर्वानुमान अभी उपलब्ध नहीं है।', mr: 'उद्याचा अंदाज आत्ता उपलब्ध नाही.', gu: 'આવતીકાલની આગાહી હમણાં ઉપલબ્ધ નથી.' },

  // ---- live translator
  tl_hint: { en: 'Say it yourself: play it in a calm voice, or copy it. Your family only receives the Signal Card below.', hi: 'इसे खुद कहें: शांत आवाज़ में सुनाएँ, या कॉपी करें। परिवार को सिर्फ़ नीचे का सिग्नल कार्ड मिलता है।', mr: 'हे स्वतः सांगा: शांत आवाजात ऐका, किंवा कॉपी करा. कुटुंबाला फक्त खालील सिग्नल कार्ड मिळते.', gu: 'આ જાતે કહો: શાંત અવાજમાં સાંભળો, અથવા કૉપી કરો. પરિવારને ફક્ત નીચેનું સિગ્નલ કાર્ડ મળે છે.' },
